), nuevos as (
  insert into public.productos (nombre, categoria, tipo, proveedor, precio, stock, stock_min, unidad)
  select d.nombre, d.categoria, 'propio', 'Formaplax', d.precio, d.stock, 0, d.unidad from datos d
  where not exists (select 1 from public.productos p where lower(p.nombre) = lower(d.nombre))
  returning id, nombre
)
insert into public.producto_costos (producto_id, costo)
select n.id, d.costo from nuevos n join datos d on d.nombre = n.nombre
on conflict (producto_id) do update set costo = excluded.costo;
